static Task SingleEntryReleaseManifestContract()
{
    using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256);var manifest=M2();Sign(manifest,key);
    VerifiedClientManifest verified=new SignedManifestVerifier(new Clock(),new Version(1,0,0)).Verify(manifest,
        new("test-only",Convert.ToBase64String(key.ExportSubjectPublicKeyInfo())));
    True(verified.RootRequiredFiles.Any(file=>file.RelativePath=="TQPlat.dll"));
    True(verified.Profiles.Single(profile=>profile.Id==ClientProfileId.Dx9).RequiredFiles.All(file=>
        file.RelativePath.Replace('\\','/').StartsWith("Env_DX9/",StringComparison.OrdinalIgnoreCase)));
    var invalid=M2();RequiredProfileFile root=invalid.RootRequiredFiles.Single(file=>file.RelativePath=="TQPlat.dll");
    invalid.RootRequiredFiles.Remove(root);invalid.Profiles.Single(profile=>profile.Id=="dx9").RequiredFiles.Add(root);Sign(invalid,key);
    Throws<InvalidDataException>(()=>new SignedManifestVerifier(new Clock(),new Version(1,0,0)).Verify(invalid,
        new("test-only",Convert.ToBase64String(key.ExportSubjectPublicKeyInfo()))));return Task.CompletedTask;
}
static Task ManifestSignatureMatrix()
{
    using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256);using var wrong=ECDsa.Create(ECCurve.NamedCurves.nistP256);
    var manifest=M2();Sign(manifest,key);var trust=new ManifestTrust("test-only",Convert.ToBase64String(key.ExportSubjectPublicKeyInfo()));
    Verify(manifest,trust);Throws<CryptographicException>(()=>Verify(manifest,new("test-only",Convert.ToBase64String(wrong.ExportSubjectPublicKeyInfo()))));
    var malformed=Clone(manifest);malformed.Signature.ValueBase64="not-base64";Throws<CryptographicException>(()=>Verify(malformed,trust));
    var keyId=Clone(manifest);keyId.Signature.KeyId="other-key";Throws<CryptographicException>(()=>Verify(keyId,trust));
    var mutated=Clone(manifest);mutated.ManifestVersion+="-mutated";Throws<CryptographicException>(()=>Verify(mutated,trust));
    var der=Clone(manifest);der.Signature.ValueBase64=Convert.ToBase64String(key.SignData(
        SignedManifestCanonicalizer.Canonicalize(der),HashAlgorithmName.SHA256,DSASignatureFormat.Rfc3279DerSequence));
    Throws<CryptographicException>(()=>Verify(der,trust));
    JsonObject source=JsonNode.Parse(JsonSerializer.Serialize(manifest))!.AsObject();var reversed=new JsonObject();
    foreach(KeyValuePair<string,JsonNode?> property in source.Reverse())reversed.Add(property.Key,property.Value?.DeepClone());
    byte[] json=Encoding.UTF8.GetBytes("\r\n  "+reversed.ToJsonString()+"\r\n");var jsonOptions=new JsonSerializerOptions{PropertyNameCaseInsensitive=true};
    Verify(JsonSerializer.Deserialize<SignedClientManifest>(json,jsonOptions)!,trust);
    byte[] bom=Encoding.UTF8.GetPreamble().Concat(json).ToArray();
    Throws<JsonException>(()=>JsonSerializer.Deserialize<SignedClientManifest>(bom,jsonOptions));
    return Task.CompletedTask;
}
static void Verify(SignedClientManifest manifest,ManifestTrust trust)=>new SignedManifestVerifier(new Clock(),new Version(1,0,0)).Verify(manifest,trust);
static void Sign(SignedClientManifest manifest,ECDsa key){manifest.Signature.KeyId="test-only";manifest.Signature.ValueBase64="";manifest.Signature.ValueBase64=Convert.ToBase64String(key.SignData(SignedManifestCanonicalizer.Canonicalize(manifest),HashAlgorithmName.SHA256));}
static SignedClientManifest Clone(SignedClientManifest manifest)=>JsonSerializer.Deserialize<SignedClientManifest>(JsonSerializer.Serialize(manifest),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})!;
static SignedClientManifest M2()
{
    SignedClientManifest manifest=M();manifest.SchemaVersion=2;manifest.ManifestVersion="owner-test-7630-single-entry-native-login-test";
    manifest.RootRequiredFiles=[new("LauncherAssets/RevoraNativeLogin.dll",1,new string('A',64),true),new("LauncherAssets/RevoraNativeLoginLoader.exe",1,new string('B',64),true),new("TQPlat.dll",1,new string('C',64),true)];
    foreach(ManifestProfile profile in manifest.Profiles)profile.CriticalLaunchFiles=[profile.RequiredFiles.Single(file=>file.RelativePath.EndsWith("Conquer.exe",StringComparison.OrdinalIgnoreCase))];
    return manifest;
}
